SELECT cr.cr_returned_date_sk, w.w_warehouse_name, cr.cr_return_quantity, cr.cr_return_amount, (cr.cr_return_quantity * cr.cr_return_amount) AS return_line_total, CASE WHEN cr.cr_return_amount > 64.32 THEN cr.cr_return_amount * 1.05 ELSE cr.cr_return_amount * 0.95 END AS adjusted_return_amount, CASE WHEN w.w_state = CAST('MN' AS varchar) THEN 'West Coast' ELSE 'Other' END AS region_category, w.w_gmt_offset + 0.5 AS gmt_offset_adjusted, COALESCE(cr.cr_fee, 0) * 2 AS double_fee FROM catalog_returns cr JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk WHERE cr.cr_return_quantity > 8 AND w.w_city = CAST('Liberty' AS varchar)
